#!/usr/bin/env bun
/**
 * Build script for han CLI binary.
 *
 * This script compiles the TypeScript source directly to a standalone binary
 * using `bun build --compile`.
 *
 * Since bun build --compile doesn't support --define, we generate a build-info
 * file that gets imported by the main module.
 *
 * The han-coordinator binary is built separately by the Rust workspace
 * (packages/han-rs) and distributed alongside the CLI binary.
 *
 * Usage:
 *   bun scripts/build-bundle.js [target]
 *
 * Targets:
 *   - bun (default, current platform)
 *   - bun-darwin-arm64
 *   - bun-darwin-x64
 *   - bun-linux-x64
 *   - bun-linux-arm64
 *   - bun-windows-x64
 */
import { createHash } from 'node:crypto';
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  writeFileSync,
} from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const packageJson = JSON.parse(
  readFileSync(join(__dirname, '..', 'package.json'), 'utf-8')
);

const version = packageJson.version;

// Read the detect-plugins prompt
const detectPluginsPrompt = readFileSync(
  join(__dirname, '..', 'lib', 'analyze', 'detect-plugins-prompt.md'),
  'utf-8'
);

let target = 'bun';
let isRelease = false;
let coordinatorFile = null;
let dashboardDir = null;

for (let i = 2; i < Bun.argv.length; i++) {
  const arg = Bun.argv[i];
  if (arg === '--release') {
    isRelease = true;
  } else if (arg === '--coordinator' && i + 1 < Bun.argv.length) {
    coordinatorFile = Bun.argv[++i];
  } else if (arg.startsWith('--coordinator=')) {
    coordinatorFile = arg.slice('--coordinator='.length);
  } else if (arg === '--dashboard' && i + 1 < Bun.argv.length) {
    dashboardDir = Bun.argv[++i];
  } else if (arg.startsWith('--dashboard=')) {
    dashboardDir = arg.slice('--dashboard='.length);
  } else if (!arg.startsWith('-')) {
    target = arg;
  }
}

let coordinatorSha256 = null;
if (isRelease && coordinatorFile && existsSync(coordinatorFile)) {
  const bytes = readFileSync(coordinatorFile);
  coordinatorSha256 = createHash('sha256').update(bytes).digest('hex');
  console.log(`Pinned coordinator SHA-256: ${coordinatorSha256}`);
}

const embeddedDashboardPath = join(
  __dirname,
  '..',
  'lib',
  'commands',
  'browse',
  'embedded-dashboard.generated.ts'
);
if (dashboardDir && existsSync(dashboardDir)) {
  let importIndex = 0;
  const importStatements = [];
  const assetEntries = [];
  function walk(dir, relPrefix = '') {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = resolve(dir, entry.name);
      const rel = `${relPrefix}/${entry.name}`;
      if (entry.isDirectory()) {
        walk(full, rel);
      } else if (entry.isFile()) {
        const varName = `asset_${importIndex++}`;
        importStatements.push(
          `import ${varName} from ${JSON.stringify(full)} with { type: 'file' };`
        );
        assetEntries.push(`  ${JSON.stringify(rel)}: ${varName},`);
        if (rel === '/index.html') {
          assetEntries.push(`  '/': ${varName},`);
        }
      }
    }
  }
  walk(dashboardDir);
  const embeddedContent = `// Auto-generated by build-bundle.js - DO NOT EDIT
${importStatements.join('\n')}

export const EMBEDDED_DASHBOARD_ASSETS: Record<string, string> = {
${assetEntries.join('\n')}
};
`;
  writeFileSync(embeddedDashboardPath, embeddedContent);
  console.log(`Generated embedded dashboard with ${importIndex} assets`);
} else {
  const embeddedContent = `// Auto-generated stub - DO NOT EDIT
export const EMBEDDED_DASHBOARD_ASSETS: Record<string, string> = {};
`;
  writeFileSync(embeddedDashboardPath, embeddedContent);
}

const isCurrentPlatform = target === 'bun';
const outfile = isCurrentPlatform
  ? join(__dirname, '..', 'dist', 'han')
  : join(
      __dirname,
      '..',
      'dist',
      'binaries',
      `han-${target.replace('bun-', '')}`
    );

console.log(`Building han v${version} for ${target}...`);

// Ensure output directory exists
mkdirSync(dirname(outfile), { recursive: true });

// Generate build-info.ts with version and prompt embedded
const buildInfoPath = join(__dirname, '..', 'lib', 'build-info.generated.ts');
writeFileSync(
  buildInfoPath,
  `// Auto-generated by build-bundle.js - DO NOT EDIT
export const HAN_VERSION = ${JSON.stringify(version)};
export const COORDINATOR_SHA256: string | null = ${JSON.stringify(coordinatorSha256)};
export const DETECT_PLUGINS_PROMPT = ${JSON.stringify(detectPluginsPrompt)};
`
);

// Compile using bun build --compile
// Externalize heavy dependencies that are only needed at runtime for specific commands
const proc = Bun.spawn(
  [
    'bun',
    'build',
    '--compile',
    '--minify',
    `--target=${target}`,
    // Externalize Next.js and its ecosystem (only used by browse command)
    '--external',
    'next',
    '--external',
    'react-server-dom-webpack',
    '--external',
    'react-server-dom-turbopack',
    '--external',
    'critters',
    '--external',
    'webpack',
    '--external',
    'sass',
    // Externalize vite and its native dependencies (used by browse command)
    '--external',
    'vite',
    '--external',
    'lightningcss',
    join(__dirname, '..', 'lib', 'main.ts'),
    '--outfile',
    outfile,
  ],
  {
    cwd: join(__dirname, '..'),
    stdout: 'inherit',
    stderr: 'inherit',
  }
);

const exitCode = await proc.exited;
if (exitCode !== 0) {
  console.error('Build failed');
  process.exit(exitCode);
}

console.log(`Built successfully: ${outfile}`);
